#include "table_design_internal.hpp"
#include <QJsonArray>
#include <QSet>
#include <algorithm>
namespace navidog {
using namespace design;
QString tableObjectKindKey(TableObjectKind kind){switch(kind){case TableObjectKind::Index:return "index";case TableObjectKind::ForeignKey:return "foreignKey";case TableObjectKind::Check:return "check";case TableObjectKind::Trigger:return "trigger";}return {};}
QString tableObjectKindName(TableObjectKind kind){switch(kind){case TableObjectKind::Index:return "索引";case TableObjectKind::ForeignKey:return "外键";case TableObjectKind::Check:return "检查";case TableObjectKind::Trigger:return "触发器";}return {};}
QString formatIdentifierList(const QStringList& values,DatabaseKind k){QStringList out;for(auto s:values)out<<quoteIdentifier(s,k);return out.join(", ");}
QStringList parseIdentifierList(const QString& source){auto ts=tokens(source,K::SQLServer);QStringList out;bool expect=true;for(const auto& t:ts){if(t.kind==sql::TokenKind::Comment)fail("字段列表不能包含注释");if(expect){if(t.kind!=sql::TokenKind::Word && t.kind!=sql::TokenKind::Identifier)fail("字段列表请使用名称，多个字段用逗号分隔");out<<unquote(t.text);expect=false;}else{if(t.text!=",")fail("字段列表请用逗号分隔；特殊名称使用双引号");expect=true;}}if(expect && !out.isEmpty())fail("字段列表末尾不能是逗号");return out;}
bool sameTableStructure(const TableDefinition& a,const TableDefinition& b){auto left=a.objects,right=b.objects;auto order=[](const auto& x,const auto& y){return std::tie(x.kind,x.name)<std::tie(y.kind,y.name);};std::sort(left.begin(),left.end(),order);std::sort(right.begin(),right.end(),order);return a.columns==b.columns && left==right && std::tie(a.comment,a.primaryKeyName,a.engine,a.charset,a.collation,a.rowFormat,a.tablespace,a.rawSql,a.sqlMode,a.withoutRowid,a.strict)==std::tie(b.comment,b.primaryKeyName,b.engine,b.charset,b.collation,b.rowFormat,b.tablespace,b.rawSql,b.sqlMode,b.withoutRowid,b.strict);}
namespace {
QString action(const QString& s){auto value=s.trimmed().toUpper();if(!QStringList{"NO ACTION","RESTRICT","CASCADE","SET NULL","SET DEFAULT"}.contains(value))fail("外键操作不支持："+s);return value;}
QString constraintSql(const ConnectionProfile& p,const TableObject& o){const auto k=p.driver;name(o.name);if(!o.sql.trimmed().isEmpty()){expression(o.sql,k);return o.sql;}QString out="CONSTRAINT "+quoteIdentifier(o.name,k)+" ";
    if(o.kind==TableObjectKind::ForeignKey){if(o.columns.isEmpty() || o.columns.size()!=o.referenceColumns.size())fail("外键本地字段与引用字段数量必须相同");name(o.referenceTable);auto n=CatalogNode{};n.object=o.referenceTable;if(mysql(k))n.database=o.referenceSchema;else n.schema=o.referenceSchema;out+="FOREIGN KEY ("+formatIdentifierList(o.columns,k)+") REFERENCES "+tableQualifiedName(p,n)+" ("+formatIdentifierList(o.referenceColumns,k)+")";
        auto del=action(o.onDelete),upd=action(o.onUpdate);if(k==K::Oracle){if(upd!="NO ACTION")fail("Oracle 不支持外键 ON UPDATE");if(del!="NO ACTION" && del!="CASCADE" && del!="SET NULL")fail("Oracle 删除规则仅支持 NO ACTION / CASCADE / SET NULL");if(del!="NO ACTION")out+=" ON DELETE "+del;}else{if(mysql(k) && (del=="SET DEFAULT" || upd=="SET DEFAULT"))fail("MySQL / OceanBase 不支持 SET DEFAULT 外键规则");if(k==K::SQLServer && (del=="RESTRICT" || upd=="RESTRICT"))fail("SQL Server 请使用 NO ACTION 代替 RESTRICT");out+=" ON DELETE "+del+" ON UPDATE "+upd;}
    }else if(o.kind==TableObjectKind::Check){if(o.expression.trimmed().isEmpty())fail("请填写检查表达式");expression(o.expression,k);out+="CHECK ("+o.expression+")";
    }else if(o.kind==TableObjectKind::Index && o.constraint){if(o.expression.isEmpty())fail("唯一约束需要字段");expression("("+o.expression+")",k);out+="UNIQUE ("+o.expression+")";}else fail("无效的约束类型");
    if(o.deferrable){if(k!=K::PostgreSQL && k!=K::Oracle && k!=K::SQLite)fail("该引擎不支持可延迟约束");out+=" DEFERRABLE";if(o.initiallyDeferred)out+=" INITIALLY DEFERRED";}
    if(mysql(k) && o.kind==TableObjectKind::Check && !o.enabled){if(k==K::MariaDB)fail("MariaDB 不支持逐个禁用 CHECK 约束，请保留启用状态。");out+=" NOT ENFORCED";}if(k==K::Oracle && !o.enabled)out+=" DISABLE";
    return out;
}
void validateObjectSql(const ConnectionProfile& p,const TableDefinition& d,const TableObject& o){auto ts=tokens(o.sql,p.driver);int first=0;while(first<ts.size() && ts[first].kind==sql::TokenKind::Comment)++first;if(first>=ts.size() || ts[first].text.compare("CREATE",Qt::CaseInsensitive)!=0)fail("对象完整定义必须以 CREATE 开始");int start=-1,on=-1;auto word=o.kind==TableObjectKind::Trigger?QString("TRIGGER"):QString("INDEX");for(int i=0;i<ts.size();++i){if(start<0 && ts[i].kind==sql::TokenKind::Word && ts[i].text.compare(word,Qt::CaseInsensitive)==0){start=i+1;continue;}if(start>=0 && ts[i].kind==sql::TokenKind::Word && ts[i].text.compare("ON",Qt::CaseInsensitive)==0){on=i+1;break;}}if(start<0 || on<0)fail("对象定义需要 CREATE "+word+" … ON 当前表");auto identity=[&](int i){QStringList parts;if(i+2<ts.size() && ts[i].text.compare("IF",Qt::CaseInsensitive)==0)i+=3;if(i<ts.size() && ts[i].text.compare("ONLY",Qt::CaseInsensitive)==0)++i;while(i<ts.size()){if(ts[i].kind!=sql::TokenKind::Word && ts[i].kind!=sql::TokenKind::Identifier)break;parts<<unquote(ts[i++].text);if(i>=ts.size() || ts[i].text!=".")break;++i;}return parts;};auto name=identity(start),table=identity(on);if(name.isEmpty() || name.last()!=o.name)fail("完整定义中的对象名称必须与名称列一致："+o.name);if(table.isEmpty() || table.last()!=d.node.object)fail("完整定义的 ON 目标必须是当前表："+d.node.object);auto schema=mysql(p.driver)?d.node.database:d.node.schema;if(table.size()>1 && !schema.isEmpty() && table[table.size()-2]!=schema)fail("完整定义的数据库 / Schema 与当前表不一致");}
QString indexSql(const ConnectionProfile& p,const TableDefinition& d,const TableObject& o){auto k=p.driver;name(o.name);if(!o.sql.trimmed().isEmpty()){validateObjectSql(p,d,o);return o.sql.trimmed();}if(o.expression.trimmed().isEmpty())fail("请填写索引字段或表达式");expression("("+o.expression+")",k);if(!o.predicate.trimmed().isEmpty())expression(o.predicate,k);
    auto method=o.method.trimmed().toUpper();if(!method.isEmpty() && !QRegularExpression("^[A-Z][A-Z0-9_]*$").match(method).hasMatch())fail("索引方法格式无效");
    auto index=quoteIdentifier(o.name,k);if(k==K::SQLite || k==K::Oracle)index=qualifiedObject(p,d.node,o.name);
    auto table=tableQualifiedName(p,d.node);if(k==K::SQLite)table=quoteIdentifier(d.node.object,k);
    QString out="CREATE "+QString(o.unique?"UNIQUE ":"");
    if(mysql(k) && (method=="FULLTEXT" || method=="SPATIAL")){if(o.unique)fail("FULLTEXT / SPATIAL 索引不能为 UNIQUE");out+=method+" ";method.clear();}
    if(k==K::SQLServer && (method=="CLUSTERED" || method=="NONCLUSTERED"))out+=method+" ";
    out+="INDEX "+index+" ON "+table;
    if(navidog::usesNativePostgres(k) && !method.isEmpty())out+=" USING "+method;
    else if(!mysql(k) && !method.isEmpty() && method!="BTREE" && method!="NORMAL" && method!="NONCLUSTERED" && method!="CLUSTERED")fail("该引擎不支持索引方法："+method);
    out+=" ("+o.expression+")";if(mysql(k) && !method.isEmpty())out+=" USING "+method;
    if(!o.predicate.trimmed().isEmpty()){if(k!=K::SQLite && k!=K::PostgreSQL && k!=K::SQLServer)fail("该引擎不支持筛选索引");out+=" WHERE "+o.predicate;}
    if(mysql(k) && !o.comment.isEmpty())out+=" COMMENT "+ddlLiteral(o.comment,k);return out;
}
QString dropObject(const ConnectionProfile& p,const TableDefinition& d,const TableObject& o){auto k=p.driver;auto table=tableQualifiedName(p,d.node);auto n=quoteIdentifier(o.name,k);
    if(o.kind==TableObjectKind::Index && !o.constraint){if(mysql(k) || k==K::SQLServer)return "DROP INDEX "+n+" ON "+table;return "DROP INDEX "+qualifiedObject(p,d.node,o.name);}
    if(o.kind==TableObjectKind::Trigger){if(navidog::usesNativePostgres(k))return "DROP TRIGGER "+n+" ON "+table;return "DROP TRIGGER "+qualifiedObject(p,d.node,o.name);}
    return "ALTER TABLE "+table+" DROP "+QString(mysql(k)?o.kind==TableObjectKind::ForeignKey?"FOREIGN KEY ":o.kind==TableObjectKind::Check?(k==K::MariaDB?"CONSTRAINT ":"CHECK "):"INDEX ":"CONSTRAINT ")+n;
}
bool stateOnly(const TableObject& old,const TableObject& current){if(old.enabled==current.enabled)return false;auto compare=current;compare.enabled=old.enabled;return compare==old;}
QString stateSql(const ConnectionProfile& p,const TableDefinition& d,const TableObject& o){auto k=p.driver;auto table=tableQualifiedName(p,d.node),name=quoteIdentifier(o.name,k);if(o.kind==TableObjectKind::Trigger){if(navidog::usesNativePostgres(k))return "ALTER TABLE "+table+(o.enabled?" ENABLE TRIGGER ":" DISABLE TRIGGER ")+name;if(k==K::Oracle)return "ALTER TRIGGER "+qualifiedObject(p,d.node,o.name)+(o.enabled?" ENABLE":" DISABLE");if(k==K::SQLServer)return QString(o.enabled?"ENABLE":"DISABLE")+" TRIGGER "+qualifiedObject(p,d.node,o.name)+" ON "+table;}
    if((o.kind==TableObjectKind::Check || o.kind==TableObjectKind::ForeignKey) && !o.constraint){if(navidog::usesNativePostgres(k) && o.enabled)return "ALTER TABLE "+table+" VALIDATE CONSTRAINT "+name;if(k==K::Oracle)return "ALTER TABLE "+table+(o.enabled?" ENABLE VALIDATE CONSTRAINT ":" DISABLE CONSTRAINT ")+name;if(k==K::SQLServer)return "ALTER TABLE "+table+(o.enabled?" WITH CHECK CHECK CONSTRAINT ":" NOCHECK CONSTRAINT ")+name;if(mysql(k) && o.kind==TableObjectKind::Check){if(k==K::MariaDB)fail("MariaDB 不支持逐个启停 CHECK 约束。");return "ALTER TABLE "+table+" ALTER CHECK "+name+(o.enabled?" ENFORCED":" NOT ENFORCED");}}return {};}
bool changed(const TableObject& old,const TableDefinition& after){auto it=std::find_if(after.objects.begin(),after.objects.end(),[&](const auto& o){return o.kind==old.kind && o.originalName==old.name;});return it==after.objects.end() || *it!=old;}
}
QStringList tableConstraints(const ConnectionProfile& p,const TableDefinition& d){QStringList out;QSet<QString> names;for(const auto& o:d.objects){auto key=o.name.toCaseFolded();if(o.kind==TableObjectKind::ForeignKey || o.kind==TableObjectKind::Check || o.constraint){if(!o.enabled && (navidog::usesNativePostgres(p.driver) || p.driver==K::SQLServer))continue;if(names.contains(key))fail("表约束名称重复："+o.name);names.insert(key);out<<constraintSql(p,o);}}return out;}
QStringList tableObjectDrops(const ConnectionProfile& p,const TableDefinition& before,const TableDefinition& after){QStringList out;auto objects=before.objects;std::stable_sort(objects.begin(),objects.end(),[](const auto& a,const auto& b){auto priority=[](const auto& o){return o.kind==TableObjectKind::ForeignKey?0:o.kind==TableObjectKind::Check?1:o.kind==TableObjectKind::Trigger?2:3;};return priority(a)<priority(b);});for(const auto& o:objects)if(changed(o,after)){auto current=std::find_if(after.objects.begin(),after.objects.end(),[&](const auto& a){return a.kind==o.kind && a.originalName==o.name;});if(current!=after.objects.end() && stateOnly(o,*current) && !stateSql(p,after,*current).isEmpty())continue;if(!o.protectedReason.isEmpty())fail(o.protectedReason);if(p.driver==K::SQLite && (o.kind==TableObjectKind::ForeignKey || o.kind==TableObjectKind::Check || o.constraint))continue;out<<dropObject(p,before,o);}return out;}
QStringList tableObjectCreates(const ConnectionProfile& p,const TableDefinition& before,const TableDefinition& after){QStringList out;auto k=p.driver;auto table=tableQualifiedName(p,after.node);QSet<QString> names;for(const auto& o:after.objects){name(o.name);auto key=tableObjectKindKey(o.kind)+":"+o.name.toCaseFolded();if(names.contains(key))fail("对象名称重复："+o.name);names.insert(key);auto old=std::find_if(before.objects.begin(),before.objects.end(),[&](const auto& a){return a.kind==o.kind && a.name==o.originalName;});if(old!=before.objects.end() && *old==o)continue;if(old!=before.objects.end() && stateOnly(*old,o)){auto statement=stateSql(p,after,o);if(!statement.isEmpty()){out<<statement;continue;}}if(!o.protectedReason.isEmpty())fail(o.protectedReason);
        if(o.kind==TableObjectKind::Index && !o.constraint){out<<indexSql(p,after,o);if(navidog::usesNativePostgres(k) && !o.comment.isEmpty())out<<"COMMENT ON INDEX "+qualifiedObject(p,after.node,o.name)+" IS "+ddlLiteral(o.comment,k);}
        else if(o.kind==TableObjectKind::Trigger){if(o.sql.trimmed().isEmpty())fail("请填写完整 CREATE TRIGGER 定义");validateObjectSql(p,after,o);auto ts=tokens(o.sql,k);int i=0;while(i<ts.size() && ts[i].kind==sql::TokenKind::Comment)++i;QString prefix;for(int j=i;j<qMin(int(ts.size()),i+40);++j)prefix+=ts[j].text.toUpper()+" ";if(!prefix.startsWith("CREATE ") || !prefix.contains("TRIGGER "))fail("触发器需要完整的 CREATE TRIGGER 定义");out<<o.sql;if(!o.enabled && (navidog::usesNativePostgres(k) || k==K::SQLServer || k==K::Oracle))out<<(navidog::usesNativePostgres(k)?"ALTER TABLE "+table+" DISABLE TRIGGER "+quoteIdentifier(o.name,k):k==K::SQLServer?"DISABLE TRIGGER "+qualifiedObject(p,after.node,o.name)+" ON "+table:"ALTER TRIGGER "+qualifiedObject(p,after.node,o.name)+" DISABLE");}
        else if((before.exists || !o.enabled) && k!=K::SQLite){auto definition=constraintSql(p,o);if(navidog::usesNativePostgres(k) && !o.enabled)definition+=" NOT VALID";out<<"ALTER TABLE "+table+(k==K::SQLServer && !o.enabled?" WITH NOCHECK ADD ":" ADD ")+definition;if(k==K::SQLServer && !o.enabled)out<<"ALTER TABLE "+table+" NOCHECK CONSTRAINT "+quoteIdentifier(o.name,k);}
    }return out;}
QString tableOptionsSql(const ConnectionProfile& p,const TableDefinition& d){QString out;auto ident=[&](const QString& value){if(!QRegularExpression("^[A-Za-z][A-Za-z0-9_]*$").match(value).hasMatch())fail("表选项格式无效："+value);return value;};
    if(mysql(p.driver)){if(!d.engine.isEmpty())out+=" ENGINE="+ident(d.engine);if(!d.charset.isEmpty())out+=" DEFAULT CHARACTER SET="+ident(d.charset);if(!d.collation.isEmpty())out+=" COLLATE="+ident(d.collation);if(!d.rowFormat.isEmpty())out+=" ROW_FORMAT="+ident(d.rowFormat);if(!d.comment.isEmpty())out+=" COMMENT="+ddlLiteral(d.comment,p.driver);}
    if(p.driver==K::SQLite){if(d.withoutRowid)out+=" WITHOUT ROWID";if(d.strict)out+=d.withoutRowid?", STRICT":" STRICT";}
    if(!d.tablespace.isEmpty() && (navidog::usesNativePostgres(p.driver) || p.driver==K::Oracle))out+=" TABLESPACE "+quoteIdentifier(d.tablespace,p.driver);return out;
}
QStringList tablePropertySql(const ConnectionProfile& p,const TableDefinition& before,const TableDefinition& after){QStringList out;auto k=p.driver;auto table=tableQualifiedName(p,after.node);
    if(mysql(k) && before.exists && std::tie(before.engine,before.charset,before.collation,before.rowFormat,before.comment)!=std::tie(after.engine,after.charset,after.collation,after.rowFormat,after.comment)){auto options=tableOptionsSql(p,after);if(after.comment.isEmpty() && before.comment!=after.comment)options+=" COMMENT=''";if(!options.isEmpty())out<<"ALTER TABLE "+table+options;}
    if((navidog::usesNativePostgres(k) || k==K::Oracle) && before.comment!=after.comment)out<<"COMMENT ON TABLE "+table+" IS "+lit(after.comment,k);
    if((navidog::usesNativePostgres(k) || k==K::Oracle) && before.tablespace!=after.tablespace && !after.tablespace.isEmpty())out<<"ALTER TABLE "+table+(k==K::Oracle?" MOVE TABLESPACE ":" SET TABLESPACE ")+quoteIdentifier(after.tablespace,k);
    for(const auto& c:after.columns){auto old=std::find_if(before.columns.begin(),before.columns.end(),[&](const auto& a){return a.name==c.originalName;});auto comment=old==before.columns.end()?QString{}:old->comment;if(comment==c.comment)continue;if(navidog::usesNativePostgres(k) || k==K::Oracle)out<<"COMMENT ON COLUMN "+table+"."+quoteIdentifier(c.name,k)+" IS "+lit(c.comment,k);}
    if(k==K::SQLServer){auto property=[&](QString old,QString value,QString column){if(old==value)return;auto prefix="EXEC sys."+QString(old.isEmpty()?"sp_addextendedproperty":"sp_updateextendedproperty")+" @name=N'MS_Description', @value="+lit(value,k)+", @level0type=N'SCHEMA', @level0name="+lit(after.node.schema,k)+", @level1type=N'TABLE', @level1name="+lit(after.node.object,k);if(!column.isEmpty())prefix+=", @level2type=N'COLUMN', @level2name="+lit(column,k);out<<prefix;};property(before.comment,after.comment,{});for(const auto& c:after.columns){auto old=std::find_if(before.columns.begin(),before.columns.end(),[&](const auto& a){return a.name==c.originalName;});property(old==before.columns.end()?QString{}:old->comment,c.comment,c.name);}}
    return out;
}
QJsonObject tableDefinitionJson(const TableDefinition& d){QJsonArray cols,objects;for(const auto& c:d.columns)cols.append(QJsonObject{{"originalName",c.originalName},{"name",c.name},{"type",c.type},{"default",c.defaultExpression},{"attributes",c.attributes},{"protected",c.protectedReason},{"nullable",c.nullable},{"primaryKey",c.primaryKey},{"comment",c.comment},{"generated",c.generatedExpression},{"generation",c.generation},{"collation",c.collation},{"defaultConstraint",c.defaultConstraint},{"autoIncrement",c.autoIncrement}});for(const auto& o:d.objects)objects.append(QJsonObject{{"kind",int(o.kind)},{"originalName",o.originalName},{"name",o.name},{"expression",o.expression},{"method",o.method},{"predicate",o.predicate},{"comment",o.comment},{"columns",QJsonArray::fromStringList(o.columns)},{"referenceColumns",QJsonArray::fromStringList(o.referenceColumns)},{"referenceSchema",o.referenceSchema},{"referenceTable",o.referenceTable},{"onDelete",o.onDelete},{"onUpdate",o.onUpdate},{"sql",o.sql},{"sqlMode",o.sqlMode},{"protected",o.protectedReason},{"unique",o.unique},{"constraint",o.constraint},{"deferrable",o.deferrable},{"initiallyDeferred",o.initiallyDeferred},{"enabled",o.enabled}});return {{"columns",cols},{"objects",objects},{"comment",d.comment},{"primaryKeyName",d.primaryKeyName},{"engine",d.engine},{"charset",d.charset},{"collation",d.collation},{"rowFormat",d.rowFormat},{"tablespace",d.tablespace},{"rawSql",d.rawSql},{"sqlMode",d.sqlMode},{"withoutRowid",d.withoutRowid},{"strict",d.strict},{"detailsLoaded",d.detailsLoaded}};}
TableDefinition tableDefinitionFromJson(const QJsonObject& value){TableDefinition d;for(auto v:value["columns"].toArray()){auto a=v.toObject();TableColumn c;c.originalName=a["originalName"].toString();c.name=a["name"].toString();c.type=a["type"].toString();c.defaultExpression=a["default"].toString();c.attributes=a["attributes"].toString();c.protectedReason=a["protected"].toString();c.nullable=a["nullable"].toBool(true);c.primaryKey=a["primaryKey"].toInt();c.comment=a["comment"].toString();c.generatedExpression=a["generated"].toString();c.generation=a["generation"].toString();c.collation=a["collation"].toString();c.defaultConstraint=a["defaultConstraint"].toString();c.autoIncrement=a["autoIncrement"].toBool();d.columns<<c;}for(auto v:value["objects"].toArray()){auto a=v.toObject();TableObject o;o.kind=TableObjectKind(a["kind"].toInt());o.originalName=a["originalName"].toString();o.name=a["name"].toString();o.expression=a["expression"].toString();o.method=a["method"].toString();o.predicate=a["predicate"].toString();o.comment=a["comment"].toString();for(auto c:a["columns"].toArray())o.columns<<c.toString();for(auto c:a["referenceColumns"].toArray())o.referenceColumns<<c.toString();o.referenceSchema=a["referenceSchema"].toString();o.referenceTable=a["referenceTable"].toString();o.onDelete=a["onDelete"].toString("NO ACTION");o.onUpdate=a["onUpdate"].toString("NO ACTION");o.sql=a["sql"].toString();o.sqlMode=a["sqlMode"].toString();o.protectedReason=a["protected"].toString();o.unique=a["unique"].toBool();o.constraint=a["constraint"].toBool();o.deferrable=a["deferrable"].toBool();o.initiallyDeferred=a["initiallyDeferred"].toBool();o.enabled=a["enabled"].toBool(true);d.objects<<o;}d.comment=value["comment"].toString();d.primaryKeyName=value["primaryKeyName"].toString();d.engine=value["engine"].toString();d.charset=value["charset"].toString();d.collation=value["collation"].toString();d.rowFormat=value["rowFormat"].toString();d.tablespace=value["tablespace"].toString();d.rawSql=value["rawSql"].toString();d.sqlMode=value["sqlMode"].toString();d.withoutRowid=value["withoutRowid"].toBool();d.strict=value["strict"].toBool();d.detailsLoaded=value["detailsLoaded"].toBool();return d;}
}
